/** Default order (simulated visitor panel, 21 Oct 2026): tools for owner and
 *  finance decisions first, since their users go on to a service; the
 *  self-serve engineering tools last. The first one is featured. */
const ORDER = [
  "reporting-automation-map", "revenue-reconciliation-checklist", "hire-vs-fractional-data-team-cost", "arr-bridge-cohort-builder",
  "first-data-hire-decision-tree", "kpi-dictionary-template", "power-bi-refresh-error-lookup", "power-bi-licensing-cost-calculator",
  "saas-metrics-definitions", "data-diagnostic-checklist", "data-project-brief-template", "migration-validation-sql-generator",
  "warehouse-query-cost-estimator", "dbt-incremental-strategy-picker", "dbt-run-results-analyser", "fivetran-mar-cost-estimator",
  "backfill-planner", "data-freshness-sla-calculator",
];
const rank = (slug: string) => { const i = ORDER.indexOf(slug); return i < 0 ? ORDER.length : i; };

export const resources: Resource[] = BASE
  .map((r) => ({ ...r, ...LINKS[r.slug], sources: r.sources ?? SOURCES[r.slug], featured: r.slug === ORDER[0] }))
  .sort((a, b) => rank(a.slug) - rank(b.slug));

/** Resources folded into other pages or retired. The URL keeps working via a 307 redirect. */
export const redirectedResources: Record<string, string> = {
  "data-warehouse-readiness": "/insights/before-you-build-a-data-warehouse",
  "data-quality-checklist": "/insights/is-our-data-reliable",
  "month-end-reporting-checklist-nigeria": "/resources/reporting-automation-map",
};

export function getResource(slug: string) {
  return resources.find((r) => r.slug === slug);
}
